/// One node. The argument order is the reference dump's:
/// op, flags, min, max, cap, name, runes, subs.
fn n(
    op: u8,
    flags: u16,
    min: i64,
    max: i64,
    cap: i64,
    name: &'static str,
    runes: &[i32],
    sub: Vec<Arc<syntax::Regexp>>,
) -> Arc<syntax::Regexp> {
    let mut rs: Vec<rune> = Vec::new();
    rs.extend_from_slice(runes);
    return Arc::new(syntax::Regexp {
        Op: syntax::Op(op),
        Flags: syntax::Flags(flags),
        Sub: sub,
        Rune: rs,
        Min: int::from(min),
        Max: int::from(max),
        Cap: int::from(cap),
        Name: string::from_static(name),
    });
}



